import Foundation

/// A parsed unified / `--git` diff, broken into hunks. Used by the in-app diff viewer (issue #66)
/// to render old/new side-by-side or inline, with syntax highlighting applied per line.
struct UnifiedDiff: Equatable, Sendable {
  var hunks: [Hunk]
  /// `true` when the line cap was hit and the remainder of the diff was dropped.
  var truncated: Bool
  /// The old path from a `rename from <path>` header, when present; otherwise `nil`.
  var renamedFrom: String?

  struct Hunk: Equatable, Sendable {
    /// Verbatim `@@ -a,b +c,d @@ optional section heading` line.
    var header: String
    var lines: [Line]
  }

  struct Line: Equatable, Sendable {
    enum Kind: Equatable, Sendable {
      case context
      case addition
      case deletion
    }

    var kind: Kind
    /// Content without the leading `+`/`-`/` ` marker; no trailing newline.
    var text: String
    /// 1-based old-file line number; `nil` for additions.
    var oldLine: Int?
    /// 1-based new-file line number; `nil` for deletions.
    var newLine: Int?
  }

  /// Parse unified / `--git` diff text into hunks.
  ///
  /// Skips file headers (`diff --git`, `index`, mode lines, `---`/`+++`), captures `rename from`.
  /// Tracks old/new line numbers from each `@@` header. Stops adding lines once `lineCap` total diff
  /// lines are reached and sets `truncated = true` (the current structure is finished cleanly). A
  /// `\ No newline at end of file` marker is dropped (not a content line). Multi-file diffs have all
  /// their hunks flattened into one list in document order.
  static func parse(_ raw: String, lineCap: Int = 2000) -> UnifiedDiff {
    guard !raw.isEmpty else { return UnifiedDiff(hunks: [], truncated: false, renamedFrom: nil) }

    var hunks: [Hunk] = []
    var renamedFrom: String?
    var truncated = false
    var totalLines = 0

    // Current hunk state
    var currentHeader: String?
    var currentLines: [Line] = []
    var oldLineNo: Int = 1
    var newLineNo: Int = 1

    func flushHunk() {
      guard let header = currentHeader else { return }
      hunks.append(Hunk(header: header, lines: currentLines))
      currentHeader = nil
      currentLines = []
    }

    // Regex for @@ -oldStart[,oldCount] +newStart[,newCount] @@ [heading]
    let hhPattern = try? NSRegularExpression(
      pattern: #"^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)"#)

    for rawLine in raw.split(separator: "\n", omittingEmptySubsequences: false) {
      let line = String(rawLine)

      // File-level headers — flush the previous hunk and skip
      if line.hasPrefix("diff --git ") || line.hasPrefix("index ")
        || line.hasPrefix("new file mode") || line.hasPrefix("deleted file mode")
        || line.hasPrefix("old mode") || line.hasPrefix("new mode")
        || line.hasPrefix("similarity index") || line.hasPrefix("dissimilarity index")
        || line.hasPrefix("copy from ") || line.hasPrefix("copy to ")
        || line.hasPrefix("--- ") || line.hasPrefix("+++ ")
      {
        flushHunk()
        continue
      }

      if line.hasPrefix("rename from ") {
        flushHunk()
        renamedFrom = String(line.dropFirst("rename from ".count))
        continue
      }

      if line.hasPrefix("rename to ") {
        flushHunk()
        continue
      }

      // `\ No newline at end of file` — drop
      if line.hasPrefix("\\ ") {
        continue
      }

      // Hunk header
      if line.hasPrefix("@@") {
        flushHunk()
        if let m = hhPattern?.firstMatch(
          in: line, range: NSRange(line.startIndex..., in: line))
        {
          func capture(_ idx: Int) -> String {
            let r = m.range(at: idx)
            guard r.location != NSNotFound, let range = Range(r, in: line) else { return "" }
            return String(line[range])
          }
          oldLineNo = Int(capture(1)) ?? 1
          newLineNo = Int(capture(2)) ?? 1
        } else {
          oldLineNo = 1
          newLineNo = 1
        }
        currentHeader = line
        currentLines = []
        continue
      }

      // Hunk content — only process when we're inside a hunk
      guard currentHeader != nil else { continue }

      if truncated { continue }

      let firstChar = line.first
      switch firstChar {
      case " ":
        let text = String(line.dropFirst())
        currentLines.append(
          Line(kind: .context, text: text, oldLine: oldLineNo, newLine: newLineNo))
        oldLineNo += 1
        newLineNo += 1
        totalLines += 1
      case "+":
        let text = String(line.dropFirst())
        currentLines.append(Line(kind: .addition, text: text, oldLine: nil, newLine: newLineNo))
        newLineNo += 1
        totalLines += 1
      case "-":
        let text = String(line.dropFirst())
        currentLines.append(Line(kind: .deletion, text: text, oldLine: oldLineNo, newLine: nil))
        oldLineNo += 1
        totalLines += 1
      default:
        // Unrecognised line inside a hunk — treat as context to stay robust
        currentLines.append(
          Line(kind: .context, text: line, oldLine: oldLineNo, newLine: newLineNo))
        oldLineNo += 1
        newLineNo += 1
        totalLines += 1
      }

      if totalLines >= lineCap {
        truncated = true
      }
    }

    flushHunk()

    return UnifiedDiff(hunks: hunks, truncated: truncated, renamedFrom: renamedFrom)
  }

  /// `true` when the diff output is the binary sentinel — either the one-line
  /// `Binary files a/x and b/x differ` message, or a `GIT binary patch` block. When `true`
  /// there are no textual hunks to render.
  static func isBinary(_ raw: String) -> Bool {

/// reads empty rather than trapping.
static func rows(in rows: [[UnifiedDiff.SideBySideRow]]?, forHunk index: Int)
  -> [UnifiedDiff.SideBySideRow]
{
  guard let rows, index >= 0, index < rows.count else { return [] }
  return rows[index]
}

private func sideBySideRow(_ row: UnifiedDiff.SideBySideRow) -> some View {
  // `.top` so each side's gutter aligns to the first visual line when the taller side wraps. The
  // add/remove/absent fills are painted as a full-height background *layer* (two equal halves), not
  // per-cell: a bare cell background collapses to the gutter line under `.top` alignment, so a
  // short side opposite a multi-line wrapped side would only tint its first line. The background
  // matches the row's height (the taller side), so both halves always span the full row.
  HStack(alignment: .top, spacing: 0) {
    sideCell(row.left, side: .left)
    Divider()
    sideCell(row.right, side: .right)
  }
  .padding(.vertical, 2)  // a little line breathing room (matches the unified rows)
  .frame(maxWidth: .infinity, alignment: .leading)
  .background(
    HStack(spacing: 0) {
      sideHalfFill(row.left).frame(maxWidth: .infinity)
      sideHalfFill(row.right).frame(maxWidth: .infinity)
    }
  )
}

private enum DiffSide { case left, right }

/// One column of a side-by-side row: the old side (`.left`, deletions + context) or the new side
/// (`.right`, additions + context). A `nil` line is an absent cell — no number, just the
/// row-background layer's faint fill, so a length mismatch between the two sides reads as a gap. No
/// `+`/`-` marker: the side and colour already convey add/remove.
@ViewBuilder private func sideCell(_ line: UnifiedDiff.Line?, side: DiffSide) -> some View {
  HStack(alignment: .top, spacing: 0) {
    sideGutter(side == .left ? line?.oldLine : line?.newLine)
    if let line {
      styledText(line)
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(.leading, 4)
        .padding(.trailing, 8)
    } else {
      Color.clear.frame(maxWidth: .infinity, alignment: .leading)
    }
  }
  .frame(maxWidth: .infinity, alignment: .leading)
  .accessibilityElement(children: .ignore)
  .accessibilityIdentifier(side == .left ? "diff.side.left" : "diff.side.right")
  .accessibilityLabel(line.map(accessibilityLabel) ?? "absent")
  // Test-observable highlight marker (XCUITest can't see colours); "absent" for a blank side.
  .accessibilityValue(line.map { isHighlighted($0) ? "highlighted" : "plain" } ?? "absent")
}

/// The fill for one side, painted in the row's full-height background layer (so it spans the row
/// even when this side is shorter than a wrapping neighbour). `nil` (absent side) → a faint fill
/// derived from the muted token (no new theme/palette entry); context → clear.
private func cellFill(_ line: UnifiedDiff.Line?) -> Color {
  line.map { rowBackground($0.kind) } ?? theme.tokens.fgMuted.opacity(0.05)
}

private func hunkHeader(_ header: String) -> some View {
  Text(header)
    .font(.system(.caption, design: .monospaced))
    .foregroundStyle(theme.tokens.diffHunkFg)
    .padding(.horizontal, 8).padding(.vertical, 3)
    .frame(maxWidth: .infinity, alignment: .leading)
    .background(theme.tokens.diffHunkBg)
    .accessibilityLabel("Hunk \(header)")

}

/// Width of the two-column gutter strip: two `unifiedGutterNumber` cells (32 + 6 + 6 each).
private static let gutterWidth: CGFloat = 88

private func lineRow(_ line: UnifiedDiff.Line) -> some View {
  // `.top` so the gutter + marker align to the first visual line when a long line wraps.
  HStack(alignment: .top, spacing: 0) {
    unifiedGutter(old: line.oldLine, new: line.newLine)
    Text(marker(line.kind))
      .font(.system(.callout, design: .monospaced))
      .foregroundStyle(foreground(line.kind))
      .frame(width: 16, alignment: .center)
    styledText(line)
      .frame(maxWidth: .infinity, alignment: .leading)
      .padding(.leading, 4)
      .padding(.trailing, 8)
  }
  .padding(.vertical, 2)  // a little line breathing room
  .frame(maxWidth: .infinity, alignment: .leading)
  // Gutter tint as a full-height leading strip (spans the row's vertical padding, unlike a fill on
  // the top-aligned gutter block), painted over the row tint so the gutter reads deeper — GH-style.
  .background(alignment: .leading) { gutterFill(line.kind).frame(width: Self.gutterWidth) }
  .background(rowBackground(line.kind))
  .accessibilityElement(children: .ignore)
  .accessibilityIdentifier("diff.line")
  .accessibilityLabel(accessibilityLabel(line))
  // A test-observable marker that highlighting was applied (XCUITest can't see colours).
  .accessibilityValue(isHighlighted(line) ? "highlighted" : "plain")
}

