import Foundation

/// Where a changed-file row's diff comes from — picks the VCS revision the `DiffResolver` diffs
/// against. The Changes panel renders three contexts (issue #66 + the jj working-copy/parent split
/// landed in `2a9135e`); each row carries the source of the group it belongs to, so a click always
/// opens the *right* diff:
///   - `.gitWorktree`    — a git worktree's uncommitted changes vs `HEAD`.
///   - `.jjWorkingCopy`  — the jj working copy (`@`).
///   - `.jjParent`       — the jj working copy's parent commit (`@-`), the commit's own changes.
///   - `.commit(id)`     — an arbitrary commit's *own* changes (vs its first parent), addressed by a
///     stable commit id. The generalization of `.jjParent` used by the changeset detail (issue #59);
///     resolved structurally via `VCSProviding.fileDiff` (jj-lib / SwiftGitX), not by shelling — so
///     it works the same for jj and git repos. The revision is part of the diff's tab identity.
enum DiffSource: Equatable, Hashable, Sendable {
  case gitWorktree
  case jjWorkingCopy
  case jjParent
  case commit(String)
}

/// The `.diff` payload of a content tab (issue #66): which file, its change kind, where its diff
/// comes from, and whether the tab is still in VS-Code-style "preview" mode (italic title, replaced
/// by the next previewed file). A value type — retargeting the preview mutates a copy in place and
/// reassigns it, keeping the tab's id (and so its strip slot / split position) stable.
struct DiffDescriptor: Equatable, Hashable, Sendable {
  /// Repo-relative path (resolved against the workroom directory).
  var path: String
  var change: ChangedFile.Change
  var source: DiffSource
  /// True while this is the single preview tab for its target; false once persisted ("Keep Open",
  /// double-click, or opened persistently from the start).
  var isPreview: Bool

  /// Two descriptors address the *same* diff tab when they point at the same file from the same
  /// revision — the identity used to dedupe (re-select an already-open file) and to decide whether a
  /// preview can be retargeted in place. The preview flag is deliberately excluded.
  func sameFile(as other: DiffDescriptor) -> Bool {
    path == other.path && source == other.source
  }
}

extension DiffDescriptor: ContentDescriptor {
  func makeTabContent() -> TabContent { .diff(self) }
  func matches(_ content: TabContent) -> Bool {
    if case .diff(let d) = content { return d.sameFile(as: self) }
    return false
  }
}

import XCTest

@testable import Workroom

/// Regression tests for `DiffViewer.shouldLoad` — the load-once-per-file guard behind the diff pane's
/// `.task(id: fetchKey)`. It exists because a spurious body re-render (SwiftUI re-firing the task on
/// the same view instance after `applyHighlight` populates highlight lines, with `fetchKey`
/// UNCHANGED) used to re-enter `load()`, reset `state = .loading`, re-render, re-highlight… a ~150ms
/// feedback loop that left the pane stuck on its loader forever (issue #59). The guard must treat a
/// same-key re-fire as a no-op while still reloading on a real file switch.
final class DiffViewerLoadGuardTests: XCTestCase {

  func testFirstEverLoadRuns() {
    // No prior load (loadedKey nil) → the initial load must run.
    XCTAssertTrue(DiffViewer.shouldLoad(loadedKey: nil, fetchKey: "commit:abc\u{1F}user.rb"))
  }

  func testSameKeyReFireIsSkipped() {
    // The regression: the task re-fires with the SAME fetchKey after a highlight-driven re-render.
    // This MUST be a no-op — otherwise load() re-enters and the loader spins forever.
    let key = "commit:abc\u{1F}user.rb"
    XCTAssertFalse(
      DiffViewer.shouldLoad(loadedKey: key, fetchKey: key),
      "a re-fire with an unchanged fetchKey must not reload")
  }

  func testChangedFileReloads() {
    // A genuine file/revision switch changes fetchKey → reload.
    XCTAssertTrue(
      DiffViewer.shouldLoad(
        loadedKey: "commit:abc\u{1F}user.rb", fetchKey: "commit:abc\u{1F}post.rb"),
      "a different file must reload")
    XCTAssertTrue(
      DiffViewer.shouldLoad(
        loadedKey: "commit:abc\u{1F}user.rb", fetchKey: "commit:def\u{1F}user.rb"),
      "the same file at a different revision must reload")
  }
}

